-- ============================================================
-- Noam Keidar site — client logos schema (Phase: logos)
-- Run in the Supabase SQL Editor (same project as videos).
-- Stores logo images as base64 data-URIs directly in the table,
-- so there is NO separate storage bucket to manage.
-- ============================================================

drop table if exists public.logos cascade;

create table public.logos (
  id          bigint generated always as identity primary key,
  name_he     text not null default '',
  name_en     text not null default '',
  image_data  text not null,            -- full data:image/...;base64,... URI
  sort_order  int  not null default 0,
  is_visible  boolean not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

-- reuse the same updated_at trigger function if it exists, else create it
create or replace function public.touch_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end $$;

create trigger logos_touch
  before update on public.logos
  for each row execute function public.touch_updated_at();

create index logos_order_idx on public.logos (sort_order);

-- ============================================================
-- Row Level Security (mirrors the videos table)
-- ============================================================
alter table public.logos enable row level security;

create policy "public reads visible logos"
  on public.logos for select
  using (is_visible = true);

create policy "authenticated reads all logos"
  on public.logos for select to authenticated using (true);

create policy "authenticated can insert logos"
  on public.logos for insert to authenticated with check (true);

create policy "authenticated can update logos"
  on public.logos for update to authenticated using (true) with check (true);

create policy "authenticated can delete logos"
  on public.logos for delete to authenticated using (true);

